#if REX_PLATFORM_PROSPERO
// Port-maintained edit: preserve this include, the canonical guest-address
// helpers, and both PS5 boot-allocation branches if this file is regenerated.
#include "../../src/prospero_guest_support.h"
#endif

// HAND PATCH support: mirrors simpsons_recomp.17.cpp's
// HandPatchEnsureWritable (separate translation unit, so duplicated here).
// See that file for the full rationale, and for why this now calls
// mprotect() unconditionally rather than pre-checking /proc/self/maps
// (that check proved unreliable under heavy multi-thread load).
static bool HandPatchEnsureWritable50(void* host_addr, size_t len) {
	// HAND PATCH (neutered): the mprotect() force-writable workaround is
	// obsolete -- the runtime's AccessViolationCallback now recovers stale
	// guest-writable/host-readonly pages for ALL heap types, and doing it
	// here via raw mprotect stripped the GPU write-watch protection, which
	// broke texture upload tracking (black menu/UI). Keep the symbol so
	// call sites compile; it must do nothing.
	(void)host_addr; (void)len;
	return true;
}

// HAND PATCH support: wait briefly for another thread (or earlier init
// code) to publish a real pointer into a guest field before falling back
// to synthesizing one -- mirrors simpsons_recomp.49.cpp's
// HandPatchWaitForField49; see that copy for the boot-order-race rationale.
static uint32_t HandPatchWaitForField50(uint8_t* base, uint32_t field_guest_addr, int max_ms) {
    for (int i = 0; i < max_ms; ++i) {
        uint32_t v = REX_LOAD_U32(field_guest_addr);
        if (v >= 0x10000u) return v;
        usleep(1000);
    }
    return 0;
}

// HAND PATCH: sub_82848468's hash-table lookup/insert uses a container
// pointer at object+16 (bucket array ptr @+0, count @+4, capacity @+8) that
// is never actually initialized by any allocator reachable from this
// function (traced through sub_8283AB18 -- it only optionally adjusts an
// existing container's byte-count tracker at +36, it doesn't create one).
// Rather than track down the real constructor, self-heal: synthesize a
// valid empty hash-table container (64-entry zeroed bucket array, count=0,
// capacity=64) from a reserved, otherwise-unused high guest address range
// the first time a given object's container is found null, same technique
// as the scratch-cursor fix in simpsons_recomp.49.cpp.
static uint32_t HandPatchGetHashtableContainer50(uint32_t owner_guest_addr, uint8_t* base) {
#if REX_PLATFORM_PROSPERO
    return simpsons::GetProsperoBootAllocation(
        base, owner_guest_addr, simpsons::ProsperoBootAllocation::kHashtable);
#else
    static std::unordered_map<uint32_t, uint32_t> owners;
    auto it = owners.find(owner_guest_addr);
    if (it != owners.end()) return it->second;
    static uint32_t next_slot = 0xD0000000u;
    uint32_t container_addr = next_slot;
    next_slot += 0x1000u;  // 4KB per object: 64-byte header + 256-byte bucket array, generous margin
    fprintf(stderr, "[HANDPATCH-FIRE] HashtableContainer50 owner=0x%08x slot=0x%08x\n",
            owner_guest_addr, container_addr);
    fflush(stderr);
    owners[owner_guest_addr] = container_addr;
    HandPatchEnsureWritable50(base + container_addr, 0x1000u);
    uint32_t bucket_array_addr = container_addr + 64;
    *reinterpret_cast<uint32_t*>(base + container_addr + 0) = __builtin_bswap32(bucket_array_addr);
    *reinterpret_cast<uint32_t*>(base + container_addr + 4) = 0;   // count
    *reinterpret_cast<uint32_t*>(base + container_addr + 8) = __builtin_bswap32(64u);  // capacity
    *reinterpret_cast<uint32_t*>(base + container_addr + 36) = 0; // byte-count tracker (sub_8283AB18)
    return container_addr;
#endif
}

// HAND PATCH: sub_8283E360/sub_8283E8D0 share a lazily-allocated container
// pointer at object+20 (a resource-cache: count @+0, capacity @+4, flags
// @+8, plus fields read deeper in sub_8283E360 at container+0/-4/+12) that
// is never initialized by any allocator on this call path. Same self-heal
// technique as the hashtable container above, but with a larger zeroed
// region (multiple untraced sub-fields) and a separate reserved address
// range to avoid colliding with it.
static uint32_t HandPatchGetResourceContainer50(uint32_t owner_guest_addr, uint8_t* base) {
#if REX_PLATFORM_PROSPERO
    return simpsons::GetProsperoBootAllocation(
        base, owner_guest_addr, simpsons::ProsperoBootAllocation::kResource);
#else
    static std::unordered_map<uint32_t, uint32_t> owners;
    auto it = owners.find(owner_guest_addr);
    if (it != owners.end()) return it->second;
    static uint32_t next_slot = 0xC0000000u;
    uint32_t container_addr = next_slot;
    next_slot += 0x1000u;  // 4KB per object, generous margin for untraced fields
    fprintf(stderr, "[HANDPATCH-FIRE] ResourceContainer50 owner=0x%08x slot=0x%08x\n",
            owner_guest_addr, container_addr);
    fflush(stderr);
    owners[owner_guest_addr] = container_addr;
    HandPatchEnsureWritable50(base + container_addr, 0x1000u);
    // Entire region is already zeroed (fresh mprotect'd pages); count=0,
    // capacity=0 fall out of that. But the flags byte at +8 selects between
    // a safe "r11=0" fallback (bit 0 set) and a pointer-chase through
    // container+0 as if it were a real object pointer (bit 0 clear) in
    // sub_8283E360 -- leaving it 0 sent us down the pointer-chase with a
    // null container+0, which faulted. Set bit 0 to force the safe path.
    *reinterpret_cast<uint32_t*>(base + container_addr + 8) = __builtin_bswap32(1u);
    return container_addr;
#endif
}

